import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.CAKCj7G0.js";const P=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"理论/计算机网络/概要.md","filePath":"理论/计算机网络/概要.md","lastUpdated":1767873102000}'),r={name:"理论/计算机网络/概要.md"};function o(h,a,n,d,s,u){return e(),i("div",null,[...a[0]||(a[0]=[t('<h2 id="osi-七层网络模型" tabindex="-1">OSI 七层网络模型 <a class="header-anchor" href="#osi-七层网络模型" aria-label="Permalink to &quot;OSI 七层网络模型&quot;">​</a></h2><h3 id="物理层" tabindex="-1">物理层 <a class="header-anchor" href="#物理层" aria-label="Permalink to &quot;物理层&quot;">​</a></h3><ul><li>功能：为数据端设备透明传输数据流。</li><li>设备：中继器，集线器</li></ul><h3 id="数据链路层" tabindex="-1">数据链路层 <a class="header-anchor" href="#数据链路层" aria-label="Permalink to &quot;数据链路层&quot;">​</a></h3><ul><li>功能: 将IP数据报组装成帧交友物理层传输，通过检测、矫正物理层产生的传输差错，使得链路对网络层是一条无差错、可靠的数据传输线路。</li><li>设备: 网桥，交换机</li></ul><h3 id="网络层" tabindex="-1">网络层 <a class="header-anchor" href="#网络层" aria-label="Permalink to &quot;网络层&quot;">​</a></h3><ul><li>功能：将数据封装成数据报，通过路由为网络上的不同主机提供通信服务。</li><li>协议: IP,ICMP,ARP</li><li>设备: 路由器</li></ul><h3 id="传输层" tabindex="-1">传输层 <a class="header-anchor" href="#传输层" aria-label="Permalink to &quot;传输层&quot;">​</a></h3><ul><li>功能：负责主机中进程间通信。</li><li>协议：TCP,UDP</li></ul><h3 id="会话层" tabindex="-1">会话层 <a class="header-anchor" href="#会话层" aria-label="Permalink to &quot;会话层&quot;">​</a></h3><ul><li>功能：负责计算机软件的通信能力</li><li>协议：RPC、TLS、SSL</li></ul><h3 id="表示层" tabindex="-1">表示层 <a class="header-anchor" href="#表示层" aria-label="Permalink to &quot;表示层&quot;">​</a></h3><ul><li>功能：负责计算机软件间通信时的数据流表示形式（加密、压缩）</li></ul><h3 id="应用层" tabindex="-1">应用层 <a class="header-anchor" href="#应用层" aria-label="Permalink to &quot;应用层&quot;">​</a></h3><ul><li>功能：直接为应用进程服务。</li><li>协议：FTP(21) DNS(53) HTTP(80) DHCP(动态主机配置协议)</li></ul><h2 id="osi-五层模型" tabindex="-1">OSI 五层模型 <a class="header-anchor" href="#osi-五层模型" aria-label="Permalink to &quot;OSI 五层模型&quot;">​</a></h2><ul><li>表示层、会话层、传输层统称为运输层</li></ul>',17)])])}const _=l(r,[["render",o]]);export{P as __pageData,_ as default};
